const e = $input.first().json;
const topic = (e.chatInput || '').toString().replace(/\s+/g, ' ').trim();
return [{ json: { topic, sessionId: e.sessionId } }];

const cfg = $('Config').first().json;
const res = ($input.first().json.results || []).slice().sort((a, b) => (b.score || 0) - (a.score || 0));
const seen = new Set();
const out = [];
for (const r of res) {
  if (!r.url || (r.score ?? 0) < cfg.min_score) continue;
  const m = r.url.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);
  if (!m) continue;
  const host = m[1].toLowerCase();
  if (seen.has(host)) continue;
  seen.add(host);
  out.push({ url: r.url, title: r.title || host });
  if (out.length >= cfg.max_sources) break;
}
return [{ json: { sources: out, candidate_count: out.length } }];

const meta = $('Split Sources').all();
const cfg = $('Config').first().json;
const MAX_CHARS = 10000;
const sources = [];
const seenStart = new Set();
$input.all().forEach((it, i) => {
  const m = (meta[i] && meta[i].json) || {};
  let t = it.json.data;
  if (typeof t !== 'string') return;               // scrape failed (error item)
  t = t.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, '')
       .replace(/!\[[^\]]*\]\([^)]*\)/g, '')       // images
       .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')    // links -> link text
       .replace(/https?:\/\/\S+/g, '')
       .replace(/\s+/g, ' ')
       .trim();
  if (t.length < 500) return;                      // too thin to be useful
  const key = t.slice(0, 200);
  if (seenStart.has(key)) return;                  // duplicate page
  seenStart.add(key);
  sources.push({ url: m.url || '', title: m.title || m.url || 'Untitled', text: t.slice(0, MAX_CHARS) });
});
sources.forEach((s, i) => { s.id = i + 1; });
const esc = s => String(s).replace(/"/g, "'");
const sourcesText = sources.map(s => `<source id="${s.id}" url="${esc(s.url)}" title="${esc(s.title)}">\n${s.text}\n</source>`).join('\n');
return [{ json: { topic: cfg.topic, sources: sources.map(({ id, url, title }) => ({ id, url, title })), source_count: sources.length, sourcesText } }];

const j = $input.first().json;
const raw = (j.text ?? j.output ?? '').toString();
const ctx = $('Build Sources').first().json;
const cfg = $('Config').first().json;
const m = raw.match(/\{[\s\S]*\}/);
if (!m) throw new Error('Analyst returned no JSON: ' + raw.slice(0, 200));
let data;
try { data = JSON.parse(m[0]); } catch (e) { throw new Error('Analyst JSON invalid: ' + e.message); }
const N = ctx.source_count;
const valid = new Set(ctx.sources.map(s => s.id));
const findings = (Array.isArray(data.findings) ? data.findings : []).map(f => {
  const ids = [...new Set((Array.isArray(f.source_ids) ? f.source_ids : []).map(Number))]
    .filter(i => valid.has(i)).sort((a, b) => a - b);
  return { title: String(f.title || '').trim(), detail: String(f.detail || '').trim(), ids, n: ids.length };
}).filter(f => f.title && f.detail && f.n >= cfg.min_sources).sort((a, b) => b.n - a.n);

const tiers = [
  ['Universal findings (all sources)', f => f.n === N],
  ['Majority findings (at least half of sources)', f => f.n < N && f.n >= Math.ceil(N / 2)],
  ['Common findings (3 or more sources)', f => f.n < Math.ceil(N / 2)],
];
let md = `## Research briefing: ${cfg.topic}\n_Based on ${N} scraped sources. Only findings supported by ${cfg.min_sources}+ sources are included; counts are verified in code._\n`;
let plain = `TOPIC: ${cfg.topic}\nSOURCES ANALYSED: ${N}\n`;
for (const [label, test] of tiers) {
  const fs = findings.filter(test);
  if (!fs.length) continue;
  md += `\n### ${label}\n`;
  plain += `\n## ${label}\n`;
  for (const f of fs) {
    md += `- **${f.title}** (${f.n} of ${N}): ${f.detail} _[sources ${f.ids.join(', ')}]_\n`;
    plain += `- ${f.title} (${f.n} of ${N} sources): ${f.detail}\n`;
  }
}
md += `\n### Sources\n` + ctx.sources.map(s => `${s.id}. [${String(s.title).replace(/[\[\]]/g, '')}](${String(s.url).replace(/\)/g, '%29')})`).join('\n');
return [{ json: { has_findings: findings.length > 0, findings, briefing_md: md, briefing_plain: plain, source_count: N } }];

const raw = ($input.first().json.text ?? $input.first().json.output ?? '').toString();
const cfg = $('Config').first().json;
const brief = $('Parse Analysis').first().json.briefing_plain;
const briefMd = $('Parse Analysis').first().json.briefing_md;
const m = raw.match(/\{[\s\S]*\}/);
if (!m) throw new Error('Writer returned no JSON: ' + raw.slice(0, 200));
let d;
try { d = JSON.parse(m[0]); } catch (e) { throw new Error('Writer JSON invalid: ' + e.message); }
const igCap = String(d.instagram_caption || '').trim();
const igVis = String(d.instagram_visual_idea || '').trim();
const ttScript = String(d.tiktok_script || '').trim();
const ttCap = String(d.tiktok_caption || '').trim();
if (!igCap && !ttScript && !ttCap) throw new Error('Writer returned empty drafts');

const flags = [];
if (igCap.length > 2200) flags.push(`Instagram caption is ${igCap.length} chars (limit 2200)`);
if ((igCap.match(/#\w+/g) || []).length > 10) flags.push('Instagram caption has more than 10 hashtags');
if (ttCap.length > 300) flags.push(`TikTok caption is ${ttCap.length} chars (target 300 or fewer)`);
const words = ttScript.split(/\s+/).filter(Boolean).length;
if (words > 130) flags.push(`TikTok script is ${words} words (target 130 or fewer, about 45 seconds)`);
const nums = t => new Set((t.replace(/#\w+/g, ' ').replace(/\b\d+\/\d+\b/g, ' ').match(/\d[\d,]*(?:\.\d+)?%?/g) || []).map(n => n.replace(/,+$/, '')));
const bn = nums(brief);
const untraced = [...nums([igCap, igVis, ttScript, ttCap].join(' '))].filter(n => !bn.has(n));
if (untraced.length) flags.push(`Numbers not found in the briefing: ${untraced.join(', ')}`);

const fence = s => '```\n' + s.replace(/`{3,}/g, "'''") + '\n```';
let out = briefMd + '\n\n---\n\n## Draft social content\n';
out += flags.length
  ? `⚠️ **Review needed:** ${flags.join('; ')}\n`
  : `✅ Automated checks passed (length limits, numbers traced to briefing). A human should still verify facts before posting.\n`;
if (igCap) out += `\n**Instagram caption** (${igCap.length} chars)\n${fence(igCap)}\n`;
if (igVis) out += `\n**Instagram visual idea**\n${fence(igVis)}\n`;
if (ttScript) out += `\n**TikTok video script** (${words} words)\n${fence(ttScript)}\n`;
if (ttCap) out += `\n**TikTok caption** (${ttCap.length} chars)\n${fence(ttCap)}\n`;
return [{ json: { output: out, flags } }];
